s=s.replace('<NumberInput label="Réf. verger · facultatif" min={1} allowDecimal={false} value={d.orchardId} onChange={(v) => setDues((rows) => rows.map((r,j) => j === i ? { ...r, orchardId: v } : r))}/>','<Select label="Verger · facultatif" searchable clearable data={(result.data?.orchards ?? []).filter((p) => p.producer === Number(d.producerId)).map((p) => ({ value: String(p.value), label: `${p.label} [${p.value}]` }))} value={d.orchardId === \'\' ? null : String(d.orchardId)} onChange={(v) => setDues((rows) => rows.map((r,j) => j === i ? { ...r, orchardId: v ?? \'\' } : r))}/>')
